#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_kohonen_update_weights_empty_loops(void) {
    // Setup: Choose inputs that cause both outer loops to have zero iterations
    // This triggers the target path where:
    // 1. First loop: x < num_out is false immediately (num_out = 0)
    // 2. Second loop: x < to_x is false immediately (to_x = 0)

    const double X[] = {0.0};  // Dummy input vector
    int num_out = 0;           // Zero output nodes - causes first loop to exit immediately
    int num_features = 1;
    double alpha = 0.1;
    int R = 1;

    // Create weight array with zero dimensions
    struct kohonen_array_3d W;
    W.dim1 = 0;
    W.dim2 = 0;
    W.dim3 = num_features;
    W.data = NULL;  // No data needed for zero dimensions

    // Create distance matrix with zero dimensions
    double **D = (double **)malloc(num_out * sizeof(double *));
    // No need to allocate rows since num_out = 0

    // Test: Call function with parameters that trigger empty loops
    double result = kohonen_update_weights(X, &W, D, num_out, num_features, alpha, R);

    // Assertions
    TEST_ASSERT_EQUAL_DOUBLE(0.0, result);  // d_min initialized to 0.0 and never changed

    // Cleanup
    free(D);
    // No need to free W.data since it's NULL
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_kohonen_update_weights_empty_loops);
    return UNITY_END();
}

